# average magnetic-well figure of merit along a flux tube
def well_depth(B_of_l, dl):
    U = sum(dl / B_of_l)                 # specific flux-tube volume
    return -dU_dpsi(U)                   # >0 -> magnetic well (stable)
# stability requires well > 0 at the operating beta

# coupled-subsystem step as a GNN (schematic)
def twin_step(state, graph):
    msgs = {}
    for (u, v) in graph.edges:
        msgs.setdefault(v, []).append(g_edge[u,v](state[u], state[v]))
    new = {}
    for v in graph.nodes:
        new[v] = f_node[v](state[v], aggregate(msgs.get(v, [])))
    return new     # one coupled advance, faster than nested solves

# invariant graph readout (order-independent)
def readout(h_nodes):
    return concat(sum(h_nodes, axis=0),
                  mean(h_nodes, axis=0),
                  max(h_nodes, axis=0))   # all permutation-invariant
